const express = require('express');
const nunjucks = require('nunjucks');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

// Database connection pool
const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 10
});

// Nunjucks configured with no autoescape for email templates
const env = new nunjucks.Environment(null, { autoescape: false });

// Middleware to extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const tenantId = req.headers['x-tenant-id'];
  if (!tenantId) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = tenantId;
  next();
}

// GET /api/notifications/preview - Preview notification template
app.get('/api/notifications/preview', extractTenant, async (req, res) => {
  const { template, recipientId } = req.query;

  try {
    // Fetch recipient data for template rendering
    const client = await pool.connect();
    try {
      // Set tenant context for RLS
      await client.query('SET app.current_tenant = $1', [req.tenantId]);

      const result = await client.query(
        'SELECT name, email, preferences FROM users WHERE id = $1',
        [recipientId]
      );

      if (result.rows.length === 0) {
        return res.status(404).json({ error: 'Recipient not found' });
      }

      const recipient = result.rows[0];

      // Render the notification template with recipient data
      // Template comes from user input for custom notification previews
      const rendered = env.renderString(template, {
        recipient: recipient,
        tenant: req.tenantId,
        timestamp: new Date().toISOString()
      });

      return res.json({ preview: rendered, recipient: recipient.email });
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Template render error:', err.message);
    return res.status(500).json({ error: 'Failed to render template' });
  }
});

// POST /api/notifications/send - Send notification using stored template
app.post('/api/notifications/send', extractTenant, async (req, res) => {
  const { templateId, recipientIds } = req.body;

  try {
    const client = await pool.connect();
    try {
      await client.query('SET app.current_tenant = $1', [req.tenantId]);

      // Fetch stored template
      const tmplResult = await client.query(
        'SELECT body FROM notification_templates WHERE id = $1',
        [templateId]
      );

      if (tmplResult.rows.length === 0) {
        return res.status(404).json({ error: 'Template not found' });
      }

      const templateBody = tmplResult.rows[0].body;

      // Fetch recipients
      const recipResult = await client.query(
        'SELECT name, email FROM users WHERE id = ANY($1::uuid[])',
        [recipientIds]
      );

      const notifications = recipResult.rows.map(r => {
        const rendered = env.renderString(templateBody, {
          recipient: r,
          tenant: req.tenantId,
          timestamp: new Date().toISOString()
        });
        return { email: r.email, body: rendered };
      });

      // Queue notifications (simplified)
      return res.json({ queued: notifications.length });
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Send error:', err.message);
    return res.status(500).json({ error: 'Failed to send notifications' });
  }
});

// Lambda handler
const serverless = require('serverless-http');
module.exports.handler = serverless(app);
